import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Permutations {
    public List<List<Integer>> permute(int[] nums) {
        List<List<Integer>> result = new ArrayList<>();
        permute(nums, 0, result);
        return result;
    }

    private void permute(int[] nums, int start, List<List<Integer>> result) {
        if (start == nums.length) {
            // Base case: All elements have been placed in the current permutation
            result.add(new ArrayList<>(Arrays.asList(nums)));
            return;
        }

        for (int i = start; i < nums.length; i++) {
            // Swap the current element with the element at the start
            swap(nums, start, i);
            // Recursively permute the array starting from the next element
            permute(nums, start + 1, result);
            // Backtrack by swapping the elements again
            swap(nums, start, i);
        }
    }

    private void swap(int[] nums, int i, int j) {
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }

    public static void main(String[] args) {
        Permutations solutions = new Permutations();

        // Test case 1
        List<List<Integer>> result1 = solutions.permute(new int[]{1,2,3});
        System.out.println(result1.equals(List.of(new ArrayList<>(Arrays.asList(1,2,3)), 
                                                 new ArrayList<>(Arrays.asList(1,3,2)), 
                                                 new ArrayList<>(Arrays.asList(2,1,3)), 
                                                 new ArrayList<>(Arrays.asList(2,3,1)), 
                                                 new ArrayList<>(Arrays.asList(3,1,2)), 
                                                 new ArrayList<>(Arrays.asList(3,2,1)))) ? "Test 1 Passed" : "Test 1 Failed");

        // Test case 2
        List<List<Integer>> result2 = solutions.permute(new int[]{0,1});
        System.out.println(result2.equals(List.of(new ArrayList<>(Arrays.asList(0,1)), 
                                                 new ArrayList<>(Arrays.asList(1,0)))) ? "Test 2 Passed" : "Test 2 Failed");

        // Test case 3
        List<List<Integer>> result3 = solutions.permute(new int[]{1});
        System.out.println(result3.equals(List.of(new ArrayList<>(Arrays.asList(1)))) ? "Test 3 Passed" : "Test 3 Failed");
