import java.util.ArrayList;
import java.util.Arrays;

public class LargestSubstringFinder {

    /**
     * Finds the largest string X such that either X or its inverse can be found as a substring of any of the given strings.
     *
     * @param strings the input list of strings
     * @return the length of the largest string
     */
    public static int findLargestSubstring(ArrayList<String> strings) {
        int maxLength = 0;
        int longestReverse = 0;

        // Check each string for its reverse
        for (String s : strings) {
            String reversed = new StringBuilder(s).reverse().toString();
            for (String element : strings) {
                if (element.contains(s) || element.contains(reversed)) {
                    maxLength = Math.max(maxLength, s.length());
                    longestReverse = Math.max(longestReverse, reversed.length());
                }
            }
        }

        // Ensure that the longest palindrome is from the original or its reverse
        return Math.max(maxLength, longestReverse);
    }

    public static void main(String[] args) {
        ArrayList<String> strings1 = new ArrayList<>(Arrays.asList("ABCD", "BCDFF", "BRCD"));
        System.out.println(findLargestSubstring(strings1)); // Expected: 2

        ArrayList<String> strings2 = new ArrayList<>(Arrays.asList("rose", "orchid"));
        System.out.println(findLargestSubstring(strings2)); // Expected: 2
    }
}
