public int findLargestSubstring(List<String> strings) {
    int largestPalindromeLength = 0;
    for (String str : strings) {
        int len = str.length();
        for (int i = 0; i <= len / 2; i++) {
            if (isPalindrome(str, i, len - i)) {
                largestPalindromeLength = Math.max(largestPalindromeLength, len);
                if (len % 2 == 0) {
                    largestPalindromeLength = Math.max(largestPalindromeLength, len - 1);
                }
            }
        }
    }
    return largestPalindromeLength;
}

private boolean isPalindrome(String str, int start, int end) {
    while (start < end) {
        if (str.charAt(start) != str.charAt(end)) {
            return false;
        }
        start++;
        end--;
    }
    return true;
}
