private static void recursivelyClean(char[][] grid, int row, int col) {
    if (row < 0 || row >= grid.length || col < 0 || col >= grid[row].length || grid[row][col] != '@') {
        return;
    }
    grid[row][col] = '.';
    recursivelyClean(grid, row - 1, col);
    recursivelyClean(grid, row + 1, col);
    recursivelyClean(grid, row, col - 1);
    recursivelyClean(grid, row, col + 1);
}
