public static int countOilDeposits(char[][] grid) {
    int count = 0;
    boolean[][] visited = new boolean[grid.length][grid[0].length];
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[0].length; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) {
                count++;
                explore(i, j, grid, visited);
            }
        }
    }
    return count;
}

private static void explore(int i, int j, char[][] grid, boolean[][] visited) {
    if (i < 0 || i >= grid.length || j < 0 || j >= grid[0].length || grid[i][j] != '@' || visited[i][j]) {
        return;
    }
    visited[i][j] = true;
    explore(i - 1, j, grid, visited); // Top
    explore(i + 1, j, grid, visited); // Bottom
    explore(i, j - 1, grid, visited); // Left
    explore(i, j + 1, grid, visited); // Right
}
