private static void markOilDeposits(char[][] grid, int row, int col) {
    if (row < 0 || row >= grid.length || col < 0 || col >= grid[0].length || grid[row][col] != '@') return;
    grid[row][col] = ' '; // Mark as visited
    markOilDeposits(grid, row - 1, col); // Up
    markOilDeposits(grid, row + 1, col); // Down
    markOilDeposits(grid, row, col - 1); // Left
    markOilDeposits(grid, row, col + 1); // Right
}
