public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Read input and store it into a two-dimensional character array. If any character of the n-th column in any row is not '2', return "cannot be travelled".
    String[][] mat = new String[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            mat[i][j] = paths[i][j] == 0 ? "0" : "1";
            if (j == n - 1 && mat[i][j].equals("0")) return "cannot be travelled";
        }
    }
    // Use dynamic programming to determine if a path exists from the start to the end. The top-left element is false unless it's '2' ('2' denotes the start).
    boolean[][] dp = new boolean[n][n];
    dp[0][0] = mat[0][0].equals("1") ? false : true;
    for (int i = 1; i < n; i++) {
        // If the top-left element is '1 or it's '2' and the previous element is false and the element directly above it is '1' or '2', OR
        // If the top-left element is '2' and the previous element is false and it directly to its left element it '1' or '2', then make dp true.
        dp[i][0] = (mat[i][0].equals("1") || (mat[i][0].equals("2") && (dp[i - 1][0] || (mat[i - 1][i] != '0'))) ? true : false;
    }
    for (int j = 1; j < n; j++) {
        // If the top-left element is '1 or it's '2' and the previous element is false and the element directly to its left is '1' or '2', OR
        // If the top-left element is '2' and the previous element is false and it directlyAbove it is '1' or '2', then make dp true.
        dp[0][j] = (mat[0][j].equals("1") || (mat[0][j].equals("2") && (dp[0][j - 1] || (mat[i][j - 1] != '0'))) ? true : false;
    }

    // Check the bottom-right element for the destination.
    if (dp[n - 1][n - 1] && mat[n - 1][n - 1].equals("2")) return "can be travelled";
    else return "cannot be travelled";
}
