```java
public class Solution {
    public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
        /** Steps:
        - Represent each n-tersection as a node in a graph.
        - Each edge represents a path between two adjacent n-tersections.
        - Perform depth-first search (DFS) from the starting n-tersection to the ending n-tersection.
        - If the DFS reaches the ending n-tersection, return "can be travelled".
        - If any part of the DFS falls outside the specified n-teresting space or loops back on itself, return "cannot be travelled".
        **/

        int uSize = n * n; // Size of the n-teresting space

        Map<Integer, Set<Integer>> graph = buildGraph(uSize, paths); // Build the graph from paths

        int[] cur = new int[]{start[0], start[1]}; // Start DFS from the starting n-tersection
        int DFSPathSize = 0;

        boolean[] visited = new boolean[uSize]; // Marked array for visited nodes 

        boolean canTravel = DFS(cur, graph, uSize, DFSPathSize, visited, end);

        if (canTravel) {
            return "can be travelled";
        } else {
            return "cannot be travelled";
        }
    }

    private static Map<Integer, Set<Integer>> buildGraph(int uSize, int[][] paths) {
        Map<Integer, Set<Integer>> graph = new HashMap<>();
        for (int i = 0; i < uSize; i++) {
            graph.put(i, new HashSet<>());
        }

        for (int[] path : paths) {
            int u = path[0] * n + path[1];
            int v = path[2] * n + path[3];
            graph.get(u).add(v);
            graph.get(v).add(u);
        }
        return graph;
    }

    private static boolean DFS(int[] cur, Map<Integer, Set<Integer>> graph, int uSize, int DFSPathSize, boolean[] visited, int[] end) {
        if (DFSPathSize == 4 || cur[0] > uSize - 1 || cur[0] < 0 || cur[1] > uSize - 1 || cur[1] < 0) {
            return false;
        }
        if (visited[cur[0] * n + cur[1]]) {
            return false;
        }
        if (Arrays.equals(cur, end)) {
            return true;
        }

        visited[cur[0] * n + cur[1]] = true;
        for (int nb : graph.get(cur[0] * n + cur[1])) {
            DFSPathSize++;
            visited[nb] = true;
            if (DFS(nb, graph, uSize, DFSPathSize, visited, end)) {
                return true;
            }
            DFSPathSize--;
            visited[nb] = false;
        }
        return false;
    }
}
