public static String simplifyFraction(int numerator, int denominator) {
    for (int i = numerator; i >= 1; i--) {
        if (numerator % i == 0 && denominator % i == 0) {
            return i + "/" + (denominator / i);
        }
    }
    return numerator + "/" + denominator;
