            idx2 = j;
        }
        for (int i = 0; i < numbers.length; i++) {
            if ( remainders[i] == 0 || remainders[i] == k - remainders[i])
                continue;
            if (arr[numbers[i]] % 2 == remainders[i] % 2)
                return false;
        }
        return true;
