public class ArrangeArray {
    public boolean canArrange(int[] arr, int k) {
        int n = arr.length;
        if (n % 2 != 0) return false;

        int[] modCount = new int[k];

        for (int num : arr) {
            int mod = num % k;
            modCount[mod]++;
        }

        int balance = 0;
        for (int i = 1; i < k; i++) {
            balance += (modCount[i] + modCount[k - i]) % 2;
        }

        return balance == 0;
    }
}
