public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Build the graph using adjacency list
    Map<Integer, List<Integer>> graph = new HashMap<>();
    for (int[] edge : edges) {
        int u = edge[0], v = edge[1];
        graph.computeIfAbsent(u, k -> new ArrayList<>()).add(v);
        graph.computeIfAbsent(v, k -> new ArrayList<>()).add(u);
    }

    int result = 0;
    // Perform DFS starting from node 0
    dfs(result, 0, graph, hasApple, new boolean[n], new boolean[n]);
    return result;
}

private void dfs(int &result, int current, Map<Integer, List<Integer>> graph, boolean[] hasApple, boolean[] visited, boolean[] AppleUpdated) {
    visited[current] = true;
    AppleUpdated[current] = hasApple[current];

    for (int neighbor : graph.getOrDefault(current, Collections.emptyList())) {
        if (!visited[neighbor]) {
            dfs(result, neighbor, graph, hasApple, visited, AppleUpdated);

            if (AppleUpdated[neighbor]) {
                // If a child has an apple, add the time to collect it and return
                result += 2;
                if (current != 0) AppleUpdated[current] = true;
            }
        }
    }
}
