public int minTime(int n, int[][] edges, boolean[] hasApple) {
        // Initialize graph using adjacency lists. Each node points to a list of its neighbors.
        List<List<Integer>> adj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }

        // Perform DFS to calculate the time required to collect all apples.
        return dfs(adj, hasApple, 0, -1);
    }

    private int dfs(List<List<Integer>> adj, boolean[] hasApple, int node, int parent) {
        int time = 0;
        for (int neighbor : adj.get(node)) {
            if (neighbor == parent) continue;
            int subTime = dfs(adj, hasApple, neighbor, node);
            if (subTime > 0 || hasApple[neighbor]) {
                time += 2 + subTime;
            }
        }
        return time;
    }
}
