public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int time = 0;
    HashSet<Integer> visited = new HashSet<>();
    HashMap<Integer, List<Integer>> adjList = new HashMap<>();

    // Build the adjacency list from the edges
    for (int[] edge : edges) {
        int u = edge[0];
        int v = edge[1];
        adjList.computeIfAbsent(u, k -> new ArrayList<>()).add(v);
        adjList.computeIfAbsent(v, k -> new ArrayList<>()).add(u);
    }

    // Recursive method to calculate time
    public void dfs(int node) {
        visited.add(node);
        for (int child : adjList.getOrDefault(node, new ArrayList<>())) {
            if (!visited.contains(child)) {
                dfs(child);
                time += 2; // Counting the round trip
                if (hasApple[child] || time == 2 || visited.contains(adjList.get(child).get(0))) {
                    time = 0; // Reset time for the next round trip
                }
            }
        }
    }

    // Starting dfs from node 0
    dfs(0);
    return time;
}
