    private int downCheck(int root, int parent, ArrayList<Integer>[] tree, boolean[] hasApple, int currentPathTime){
        currentPathTime+=2; //time to increment along the path from parent to root.

        boolean hasAnAppleOnPath =false;
        for(int child:tree[root]){
            if(child !=parent){
                if(downCheck(child,root,tree,hasApple,currentPathTime) > 0){
                    hasAnAppleOnPath = true;
                }
            }
        }

        if(hasAnApple[root]){ //If any true on this path, then all the paths down from this node has structure and additional current path time required to add into total time
            return currentPathTime;
        }else{
            return 0;
        }
    }
