import java.util.*;

public class MinTime {
    public int minTime(int n, int[][] edges, boolean[] hasApple) {
        List<List<Integer>> adjacencyList = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            adjacencyList.add(new ArrayList<>());
        }

        // Build the adjacency list from the given edges
        for (int[] edge : edges) {
            int u = edge[0], v = edge[1];
            adjacencyList.get(u).add(v);
            adjacencyList.get(v).add(u);
        }

        return timeCost(0, adjacencyList, hasApple, new HashMap<>());
    }

    private int timeCost(int curr, List<List<Integer>> adj, boolean[] hasApple, Map<Integer, Boolean> memo) {
        if (memo.containsKey(curr)) {
            return memo.get(curr) ? 0 : memo.get(curr);
        }

        int time = 0;
        // Check if the current node has an apple
        if (hasApple[curr]) {
            time = 2;
        }

        // Check neighbors
        int childrenTime = 0;
        for (int neighbor : adj.get(curr)) {
            childrenTime += timeCost(neighbor, adj, hasApple, memo);
        }
        time += childrenTime;

        // Cache the result for the current node
        memo.put(curr, time > 0);
        return time;
    }

    public static void main(String[] args) {
        MinTime minTime = new MinTime();

        // Test case 1
        int[][] edges1 = {{0,1},{0,2},{1,4},{1,5},{2,3},{2,6}};
        boolean[] hasApple1 = {false,false,true,false,true,true,false};
        System.out.println(minTime.minTime(7, edges1, hasApple1)); // Output: 8

        // Test case 2
        int[][] edges2 = {{0,1},{0,2},{1,4},{1,5},{2,3},{2,6}};
        boolean[] hasApple2 = {false,false,true,false,false,true,false};
        System.out.println(minTime.minTime(7, edges2, hasApple2)); // Output: 6

        // Test case 3
        int[][] edges3 = {{0,1},{0,2},{1,4},{1,5},{2,3},{2,6}};
        boolean[] hasApple3 = {false,false,false,false,false,false,false};
        System.out.println(minTime.minTime(7, edges3, hasApple3)); // Output: 0
    }
}
