    if (nums.length < 2) {
        return false;
    }

    int totalSum = Arrays.stream(nums).sum();
    double targetSum = totalSum / 2;

    int distinctCount = (int) Math.sqrt(nums.length);
    int count = 0;

    for (int i = 1; i <= distinctCount; i++) {
        if (totalSum % i == 0) {
            count++;
        }
    }

    int[] complement = new int[nums.length];
    for (int i = 0; i < nums.length; i++) {
        complement[(i + 1) % nums.length] = nums[i];
    }

    for (int i = 0; i < count; i++) {
        int remainingSum = totalSum - complement[i];
        if (remainingSum % i == 0) {
            return true;
        }
    }

    return false;
}
