public boolean splitArraySameAverage(int[] nums) {
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }

    int targetSum = totalSum / 2;

    int leftSum = 0;
    int rightSum = totalSum - leftSum;

    for (int i = 0, j = nums.length - 1; i != j; i++, j--) {
        leftSum += nums[i];
        rightSum -= nums[j];

        if (leftSum == targetSum) {
            return true;
        }
    }

    return totalSum == 0 && nums.length == 1;
