```java
import java.util.HashMap;

class Morse {
    public static String[] morse = {".-","-...","-.-.","-..",".","..-.","--.","....","..",".---","-.-",".-..","--","-.","---",".--.","--.-",".-.","...","-","..-","...-",".--","-..-","-.--","--.."};
    public static String encode(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            sb.append(morse[s.charAt(i) - 'a']);
        }
        return sb.toString();
    }
}

class Solution {
    public int uniqueMorseRepresentations(String[] words) {
        HashMap<String, Integer> map = new HashMap<>();
        for (String word : words) {
            String m = Morse.encode(word);
            map.put(m, map.getOrDefault(m, 0) + 1);
        }
        return map.size();
    }

    public static void main(String[] args) {
        Solution solution = new Solution();
        System.out.println(solution.uniqueMorseRepresentations(new String[]{"gin", "zen", "gig", "msg"})); // Expected: 2
        System.out.println(solution.uniqueMorseRepresentations(new String[]{"a"})); // Expected: 1
    }
}
