    int uniqueCodes = 1 << k;
    boolean[] codeBitsets = new boolean[uniqueCodes];
    for (int i = 0; i < s.length(); i++) {
        if (i + k > s.length()) break;
        int codeBits = 0;
        for (int j = i; j < i + k; j++) {
            codeBits = (codeBits << 1) | (s.charAt(j) - '0');
