import java.util.LinkedList;
import java.util.Queue;

public class MinimumFibonacciNumbers {

    public int findMinFibonacciNumbers(int k) {
        if (k < 2)
            return 0;

        Queue<Long> queue = new LinkedList<>();
        queue.add(1L);
        queue.add(1L);
        long sum = 1;
        int count = 0;

        while (sum < k) {
            long next = queue.poll();
            sum += next;
            queue.add(next);
            queue.add(next + next);
            count++;
        }

        while (k > 0) {
            if (k - queue.peek() >= 0) {
                k -= queue.poll();
                count++;
                continue;
            }
            queue.poll();
        }

        return count;
    }
}
