     * Removes adjacent characters with matching case from the string.
     *
     * @param s the input string
     * @return the "good" string after removing adjacent matching case characters
     */
    public static String makeGood(String s) {
        StringBuilder sb = new StringBuilder(s);
        int index = 0;

        while (index < sb.length() - 1) {
            char current = sb.charAt(index);
            char next = sb.charAt(index + 1);

            if (Character.toLowerCase(current) == Character.toLowerCase(next)) {
                sb.delete(index, index + 2);
                if (index > 0) {
                    index--;
