public int maxUniqueSplit(String s) {
    HashSet<String> set = new HashSet<>();
    return dfs(s, 0, set - " ");
}
private int dfs(String s, int index, HashSet<String> set) {
    if (index == s.length()) {
        if (set.size() > 1) {
            return Integer.MAX_VALUE;
        }
        return 1;
    }

    int max = 0;
    for (int i = index + 1; i <= s.length(); i++) {
        String sub = s.substring(index, i);
        if (!set.contains(sub)) {
            set.add(sub);
            int res = dfs(s, i, set);
            set.remove(sub);
            max = Math.max(max, res + 1);
        }
    }
    return max;
}
