private static int maxUniqueSplit(int start, String str) {
    if (start == str.length()) {
        return 0;
    }
    int max = 1;
    for (int i = start + 1; i <= str.length(); i++) {
        recursiveMin(max, str.substring(start, i));
    }
    return max;
}

private static void recursiveMin(int max, String str) {
    if (str.length() == 0) {
        return;
    }
    if (!str.equals(str.substring(1))) {
        max = Math.max(max, 1 + maxUniqueSplit(0, str.substring(1)));
    } else {
        max = Math.max(max, maxUniqueSplit(1, str));
    }
}
