public int maxUniqueSplit(String s) {
    int n = s.length();
    int result = 0;
    boolean[] used = new boolean[n];

    return maxUniqueSplitRecursive(s, result, used, 0);
}

private int maxUniqueSplitRecursive(String s, int result, boolean[] used, int start) {
    if (start == s.length()) {
        return result;
    }
    int max = 0;
    for (int i = start; i < s.length(); i++) {
        if (!used[i]) {
            used[i] = true;
            max = Math.max(max, maxUniqueSplitRecursive(s, result + 1, used, i + 1));
            used[i] = false;
        }
    }
    return max;
}
