private int backtracking(String s, HashSet<String> set, int index) {
    if (index == s.length()) {
        return set.size();
    }

    int max = 0;
    for (int i = index; i < s.length(); i++) {
        String sub = s.substring(index, i + 1);
        if (!set.contains(sub)) {
            set.add(sub);
            max = Math.max(max, backtracking(s, set, i + 1));
            set.remove(sub);
        }
    }
    return max;
