import java.util.Arrays;

public class SmallestString {
    public String getSmallestString(int n, int k) {
        if (n == 1) {
            return Character.toString((char) (k + 96));
        }
        String smallestStr = String.valueOf((char) (k + 96));
        for (int i = 0; k > 0 && i < n - 2; i++) {
            smallStr = 'a' + smallestStr;
            k--;
        }
        if (k > 0) {
            smallStr = 'a' + smallStr;
            k--;
            for (int i = 0; k > 0 && i < n - 1; i++) {
                smallStr = 'a' + smallStr;
                k--;
            }
            smallStr += 'a';
            k--;
        }
        return smallestStr;
    }

    public static void main(String[] args) {
        SmallestString solver = new SmallestString();
        System.out.println(solver.getSmallestString(3, 27)); // Output: "aay"
