import java.util.Arrays;

public class LexicographicallySmallestString {
    public static String getSmallestString(int n, int k) {
        if (n == 1) {
            return String.valueOf((char) ('a' + k - 1));
        }

        int[] counts = new int[26];
        Arrays.fill(counts, n);

        int reduction = k - ((n * 25) - n);
        if (reduction >= 0) {
            counts[(char) (reduction + 'a') - 1]--;
            reduction--;
        } else {
            reduction = -reduction;
        }

        for (int i = 25; i >= 0; i--) {
            counts[i] -= reduction;
            if (counts[i] >= 0) {
                reduction = 0;
            }
        }

        char smallestChar = (char) (reduction + 'a');
        String smallestString = String.valueOf(smallestChar).repeat(n);

        for (int i = 0; i < countedChar * ((not (smallestChar == 'a')) ? 2 : 1); i++) {
            smallestString = smallestChar + smallestString;
        }

        return smallestString;
    }

    public static void main(String[] args) {
        System.out.println(getSmallestString(3, 27)); // Output: "aay"
        System.out.println(getSmallestString(5, 73)); // Output: "aaszz"
    }
}
