public static double calculateProbability(int n) {
    if (n < 2) {
        return 1.0; // There is only one way for the first passenger to sit
    }
    double[] dp = new double[n + 1];
    dp[1] = 1.0; // Only the first passenger can sit in their own seat
    dp[2] = 1.0; // The first two passengers can each sit in their own seat or the second passenger can sit next to the first
    for (int i = 3; i <= n; i++) {
        dp[i] = (1 - dp[i - 1]) + dp[i -2]; // The probability for the last passenger is the sum of the probability for the first passenger not sitting in their own seat and the probability for the last passenger sitting next to the first passenger
    }
    return dp[n];
}
