public static List<Integer> findSteppingNumbers(int low, int high) {
  List<Integer> result = new ArrayList<>();
  int start = 0;
  int end = high;

  // Process numbers from start to the middle
  for (int i = start; i <= end / 2; i++) {
    if (i + 1 > high) continue;
    result.add(i);

    // Process numbers from middle to end
    // since the numbers from start to middle are in ascending order
    // numbers from middle to end will be in sorted order
    if (i + 1 < high && Math.abs(i - i + 1) <= 1) {
      result.add(i + 1);
    }
  }

  return result;
}
