            int highPart = mid / power10;
            int lowPart = mid % power10;
            int digitAtIndex = (mid - lowPart) / power10 + 1;

            if (highPart == 0) {
                onesCount += lowPart * power10;
            } else if (highPart == 1) {
                onesCount += lowPart * power10 + mid % (power10 * digitAtIndex) + 1;
            } else {
                onesCount += (highPart + 1) * power10 * digitAtIndex;
            }

            if (digitAtIndex < 2) {
                high = mid - 1;
            } else {
                low = mid + 1;
            }
            power10 *= 10;
        }
        return onesCount;
    }
