import java.lang.*;

public class PowerOfTwoChecker {
    public static boolean isPowerOfTwo(int n) {
        // Edge cases: 0 and negative numbers are not powers of two
        if (n <= 0) {
            return false;
        }

        // Shift all bits to the right until we get 1
        int shiftedN = n >> 1;

        // If shiftedN is 1 and (n & 1) is 0, n is a power of two
        return shiftedN == 1 && (n & 1) == 0;
    }
}
