            maxSum = Math.max(maxSum, helperVertical(mat, 0, row));
            maxSum = Math.max(maxSum, helperDiagonal(mat, row, 0));
            maxSum = Math.max(maxSum, helperAntidiagonal(mat, row, 0));
        }

        return maxSum;
