        int newIn = 0; // The new length of the current horizontal line
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                in = newIn + 1; // Update the length of the current horizontal line
                res = Math.max(res, in); // Update the result if the current line is longer than the previous one
            } else {
                in = 0; // Reset the length of the current horizontal line if a 0 is found
            }
            if (j == 0) {
                d0[j] = in;
            } else {
                d0[j] = d0[j - 1] + (mat[i][j] == 1 ? 1 : 0); // Update the length of the current diagonal
            }

            if (j == n - 1) {
                d3[j] = in;
            } else {
                d3[j] = d3[j + 1] + (mat[i][j] == 1 ? 1 : 0); // Update the length of the current anti-diagonal
            }

            if (d1[j] > res) res = d1[j]; // Update the result if the current vertical line is longer than the previous one
            if (d2[j] > res) res = d2[j]; // Update the result if the current two-diagonal line is longer than the previous one
        }
