            // Check horizontal continuous line
            int horizontalLength = 1;
            for (int k = 1; i + k < m && mat[i + k][j] == 1; k++) {
                horizontalLength++;
            }

            // Check vertical continuous line
            int verticalLength = 1;
            for (int k = 1; j + k < n && mat[i][j + k] == 1; k++) {
                verticalLength++;
