            int diagonalLength = 1;
            for (int k = 1; i + k < m && j + k < n && mat[i + k][j + k] == 1; k++) {
                diagonalLength++;
            }

            // Check anti-diagonal continuous line (right up)
            int antiDiagonalLength = 1;
            for (int k = 1; i + k < m && j - k >= 0 && mat[i + k][j - k] == 1; k++) {
                antiDiagonalLength++;
            }

            maxLength = Math.max(maxLength, horizontalLength, verticalLength, diagonalLength, antiDiagonalLength);
