    int maxLength = 0;

    // Iterate through the matrix
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (mat[i][j] == 1) {
                // Update longest length for right, left, up diagonal, and down diagonal
                maxRight = Math.max(maxRight + 1, 1);
                maxLeft = Math.max(maxLeft + 1, 1);
                maxUpDiag = Math.max(maxUpDiag + 1, 1);
                maxDownDiag = Math.max(maxDownDiag + 1, 1);

                // Update the maximum length of the longest line
                maxLength = Math.max(maxLength, Math.max(maxRight, Math.max(maxLeft, Math.max(maxUpDiag, maxDownDiag))));
            } else {
                // Reset the length for each direction when encountering a 0
                maxRight = 0;
                maxLeft = 0;
                maxUpDiag = 0;
                maxDownDiag = 0;
            }
        }
    }

