public static int squarePermutations(int[] A) {
    int n = A.length;
    int invCount = 0;

    // Cyclic Sort Algorithm to bring all even elements to the end
    int i = 0;
    for (int j = 0; j < n; j++) {
        if (A[j] % 2 == 0) {
            swap(A, i, j);
            i++;
        }
    }

    // Find inversions to check if the array can be arranged as square permutations
    for (int j = 0; j < n - 1; j++) {
        for (int k = j + 1; k < n; k++) {
            if (A[j] % 2 == 0 && Math.sqrt(A[j] + A[k]) % 2 == 0) {
                invCount++;
            }
        }
    }

    return invCount / 2;
}

private static void swap(int[] A, int i, int j) {
    int temp = A[i];
    A[i] = A[j];
    A[j] = temp;
}
