private static boolean isPerfectSquare(int x) {
    int s = (int)Math.sqrt(x);
    return (s * s == x);
}

private static int count_combinations(int n, int k) {
    if (k > n) return 0;
    if (k == 1) return n;
    return n * count_combinations(n - 1, k - 1) / (k * (k - 1));
}

public static int squarePermutations(int[] A) {
    if (A.length == 0) return 1;

    int result = 0;
    sortPermutations(A);

    for (int i = 0; i < A.length; i++) {
        if (!isPerfectSquare(A[i])) {
            return 0;
        }
        for (int j = 0; j < i; j++) {
            if (Math.abs(A[i] - A[j]) != 1) {
                return 0;
            }
        }
    }

    // Calculate the number of valid permutations
    result = count_combinations(A.length, countOccurrences(A, A[0])) * count_combinations(A.length - 1, countOccurrences(A, A[1]));

    return result;
}

private static int countOccurrences(int[]A, int val) {
    int count = 0;
    for (int num: A) {
        if (num == val) count++;
    }
    return count;
}

private static void sortPermutations(int[] A) {
    for (int i = 0; i < A.length; i++) {
        for (int j = i + 1; j < A.length; j++) {
            if (A[i] > A[j]) {
                int temp = A[i];
                A[i] = A[j];
                A[j] = temp;
            }
        }
    }
}
