    int[] res = new int[size1*size2];
    int j =0;
    int i =0;

    // Initialize result with zero
    while(pos < size1*size2){
        i = j;

        // For upwards diagonal
        while(i >= 0 && j < size2 && pos < size1*size2){
            res[pos++] = mat[i--][j++];
        }

        if(i == -1) j++;
        if(j == size2) i++;

        // For downwards diagonal
        i = j;
        while(i < size1 && j >= 0 && pos < size1*size2){
            res[pos++] = mat[i++][j--];
        }

        if(i == size1) j++;
        if(j == -1) i--;
    }

    return res;
}
