        for (int j = 0; j < digits.length; j++) {
            if (digits[j] == 0 && !used[j]) {
                digits[j] = s.charAt(i) - '0';
                used[j] = true;
                smallest.append(digits[j]);
                break;
            }
        }
        used = new int[10]; // Reset used array for the next digit

        if (digits[0] == s.charAt(s.length() - 1)) {
            // If found a reincrementation, go to the next digit
            continue;
        } else {
            // If all digits have already been used, stop
            break;
        }
    }

    // If there is no valid arrangement, return -1
    if (smallest.length() == s.length()) return -1;

    return Integer.parseInt(smallest.toString());
