     */
    public static int findSmallestInteger(int n) {
        if (n <= 0) {
            return -1;
        }

        // Convert the input number into a character array to manipulate digits
        char[] digits = Integer.toString(n).toCharArray();

        // Find the maximum index in the array
        int maxIndex = digits.length - 1;

        // Swap the last element with the largest element that is smaller than the last element
        for (int i = maxIndex - 1; i >= 0; i--) {
            if (digits[i] < digits[maxIndex]) {
                char temp = digits[i];
                digits[i] = digits[maxIndex];
                digits[maxIndex] = temp;
                break;
            }
        }

        // Sort the remaining elements in ascending order to form the smallest rearranged integer
        Arrays.sort(digits, 0, maxIndex);

        // Convert the character array back to an integer
        try {
            return Integer.parseInt(new String(digits));
        } catch (NumberFormatException e) {
            // Return -1 if the resulting string cannot be parsed as an integer
