     */
    public static List<String> centerSymmetricNumbers(int n) {
        ArrayList<String> centerSymmetricNumbers = new ArrayList<>();

        if (n == 1) {
            centerSymmetricNumbers.add("0");
            centerSymmetricNumbers.add("1");
            centerSymmetricNumbers.add("8");
            return centerSymmetricNumbers;
        }

        if (n % 2 != 0) {
            // Odd length center symmetric numbers
            for (int num = (int) Math.pow(10, n - 1); num < (int) Math.pow(10, n); num++) {
                StringBuilder sb = new StringBuilder(Integer.toString(num));
                sb.append(sb.reverse().substring(1));
                centerSymmetricNumbers.add(sb.toString());
            }
        } else {
            // Even length center symmetric numbers
            for (int num = (int) Math.pow(10, n - 1); num < (int) Math.pow(10, n); num++) {
                StringBuilder sb = new StringBuilder(Integer.toString(num));
                sb.append(sb.reverse().substring(1));
                int padStart = (int) Math.pow(10, n / 2 - 1);
                if (num % 2 == 0) {
                    sb.insert(padStart, "8");
                } else {
                    sb.insert(padStart, "0");
                }
                centerSymmetricNumbers.add(sb.toString());
            }
