public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }

    int count = 0;
    int multiple = 1;
    while (true) {
        if (isUgly(multiple)) {
            count++;
            if (count == n) {
                return multiple;
            }
        }
        multiple *= 5; // Consider 5x as an extension of the ugly sequence calculation
    }
