public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Index must be positive.");
    }

    PriorityQueue<Long> pq = new PriorityQueue<>();
    Set<Long> seen = new HashSet<>();
    pq.offer(1L);
    seen.add(1L);
    int count = 0;

    while (count < n) {
        long curr = pq.poll();
        count++;
        pq.offer(curr * 2);
        pq.offer(curr * 3);
        pq.offer(curr * 5);

        if (!seen.add(curr * 2)) {
            pq.offer(curr * 2);
            pq.offer(curr * 3);
        }
        if (!seen.add(curr * 3)) {
            pq.offer(curr * 3);
            pq.offer(curr * 5);
        }
        if (!seen.add(curr * 5)) {
            pq.offer(curr * 5);
        }
    }

    return (int) curr;
}
