public static String reverseWords(String s) {
    StringBuilder reversed = new StringBuilder();
    StringBuilder wordBuilder = new StringBuilder();

    for (char c : s.toCharArray()) {
        if (Character.isWhitespace(c)) {
            if (wordBuilder.length() > 0) {
                // Reverse the word and append to the result
                String currentWord = wordBuilder.toString();
                StringBuilder reversedWord = new StringBuilder(currentWord);
                for (int i = 0, j = reversedWord.length() - 1; i < j; i++, j--) {
                    char temp = reversedWord.charAt(i);
                    reversedWord.setCharAt(i, reversedWord.charAt(j));
                    reversedWord.setCharAt(j, temp);
                }
                reversed.append(reversedWord);
            }
            wordBuilder = new StringBuilder(); // Reset the word buffer
        } else {
            wordBuilder.append(c);
        }
    }

    // Append the last word, if any, to the result
    if (wordBuilder.length() > 0) {
        String lastWord = wordBuilder.toString();
        StringBuilder reversedWord = new StringBuilder(lastWord);
        for (int i = 0, j = reversedWord.length() - 1; i < j; i++, j--) {
            char temp = reversedWord.charAt(i);
            reversedWord.setCharAt(i, reversedWord.charAt(j));
            reversedWord.setCharAt(j, temp);
        }
        reversed.append(reversedWord);
    }

    return reversed.toString();
}
