import java.util.*;

public class StringReverser {
    /**
     * Reverses each word in the input string while maintaining the original word order.
     *
     * @param s The input string containing words separated by spaces.
     * @return The string with characters of each word reversed.
     */
    public static String reverseWords(String s) {
        List<String> words = Arrays.asList(s.split(" "));
        StringBuilder reversed = new StringBuilder();

        for (String word : words) {
            StringBuilder reversedWord = new StringBuilder();
            for (int i = word.length() - 1; i >= 0; i--) {
                reversedWord.append(word.charAt(i));
            }
            reversed.append(reversedWord.toString());
        }

        return reversed.toString();
